<?php
namespace Tests\Feature;
use App\Models\{InventoryLocation,Role,SupplyBatch,SupplyCategory,SupplyItem,UnitOfMeasurement,User};
use App\Services\InventoryService;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Validation\ValidationException;
use Tests\TestCase;
class AISMSInventoryTest extends TestCase {
 use RefreshDatabase;
 private function setupInventory(): array { $role=Role::create(['name'=>'Inventory','slug'=>'inventory','permissions'=>['modules.aisms.*'],'is_active'=>true]);$user=User::factory()->create();$user->roles()->attach($role);$cat=SupplyCategory::firstOrCreate(['name'=>'Seeds'],['is_active'=>true]);$unit=UnitOfMeasurement::firstOrCreate(['name'=>'Kilogram'],['symbol'=>'kg']);$loc=InventoryLocation::create(['name'=>'Warehouse','is_active'=>true]);$item=SupplyItem::create(['category_id'=>$cat->id,'unit_id'=>$unit->id,'code'=>'SEED-1','name'=>'Rice seed','minimum_stock'=>5,'status'=>'active']);return compact('user','loc','item'); }
 public function test_receipt_release_and_adjustment_persist_and_balance(): void { $x=$this->setupInventory();$service=app(InventoryService::class);$receipt=$service->receive(['supply_item_id'=>$x['item']->id,'location_id'=>$x['loc']->id,'batch_number'=>'B1','received_on'=>now()->toDateString(),'quantity'=>10],$x['user']->id);$this->assertDatabaseHas('inventory_movements',['id'=>$receipt->id,'movement_type'=>'receipt']);$this->assertSame('10.00',(string)SupplyBatch::first()->quantity_available);$service->release(['supply_batch_id'=>SupplyBatch::first()->id,'quantity'=>3,'recipient'=>'Farmer','purpose'=>'Demo'], $x['user']->id);$this->assertSame('7.00',(string)SupplyBatch::first()->fresh()->quantity_available);$service->adjust(['supply_batch_id'=>SupplyBatch::first()->id,'quantity'=>2,'adjustment_reason'=>'Count correction'],$x['user']->id);$this->assertSame('9.00',(string)SupplyBatch::first()->fresh()->quantity_available); }
 public function test_insufficient_and_expired_releases_are_rejected(): void { $x=$this->setupInventory();$service=app(InventoryService::class);$service->receive(['supply_item_id'=>$x['item']->id,'location_id'=>$x['loc']->id,'batch_number'=>'OLD','received_on'=>now()->subDays(10)->toDateString(),'expires_on'=>now()->subDay()->toDateString(),'quantity'=>2],$x['user']->id);$this->expectException(ValidationException::class);$service->release(['supply_batch_id'=>SupplyBatch::first()->id,'quantity'=>1,'recipient'=>'x','purpose'=>'x'],$x['user']->id); }
 public function test_duplicate_receipt_is_idempotent(): void { $x=$this->setupInventory();$service=app(InventoryService::class);$data=['supply_item_id'=>$x['item']->id,'location_id'=>$x['loc']->id,'batch_number'=>'B2','received_on'=>now()->toDateString(),'quantity'=>4,'idempotency_key'=>'receipt-1'];$service->receive($data,$x['user']->id);$service->receive($data,$x['user']->id);$this->assertDatabaseCount('inventory_movements',1);$this->assertSame('4.00',(string)SupplyBatch::first()->quantity_available); }
 public function test_unauthorized_user_cannot_access_inventory(): void { $user=User::factory()->create();$this->actingAs($user)->get('/modules/aisms')->assertForbidden(); }
 public function test_authorized_user_can_render_inventory_workspace(): void { $x=$this->setupInventory();$this->actingAs($x['user'])->get('/modules/aisms')->assertOk()->assertSee('Agricultural Inventory'); }
 public function test_authorized_user_can_register_supply_with_catalog_requirements(): void { $x=$this->setupInventory();$this->actingAs($x['user'])->post('/modules/aisms/items',['category_id'=>$x['item']->category_id,'unit_id'=>$x['item']->unit_id,'code'=>'SEED-2','name'=>'Corn seed','minimum_stock'=>8])->assertRedirect();$this->assertDatabaseHas('supply_items',['code'=>'SEED-2','name'=>'Corn seed','minimum_stock'=>'8.00']); }
  public function test_low_stock_stat_uses_live_supply_balances(): void { $x=$this->setupInventory();app(InventoryService::class)->receive(['supply_item_id'=>$x['item']->id,'location_id'=>$x['loc']->id,'batch_number'=>'LOW','received_on'=>now()->toDateString(),'quantity'=>2],$x['user']->id);$this->actingAs($x['user'])->get('/modules/aisms')->assertOk()->assertSee('data-aisms-stat="low-stock"',false)->assertSee('text-agricultural-gold">1</p',false); }
  public function test_receipts_reject_inactive_locations(): void { $x=$this->setupInventory();$inactive=InventoryLocation::create(['name'=>'Closed Warehouse','is_active'=>false]);$this->expectException(ValidationException::class);app(InventoryService::class)->receive(['supply_item_id'=>$x['item']->id,'location_id'=>$inactive->id,'batch_number'=>'CLOSED','received_on'=>now()->toDateString(),'quantity'=>1],$x['user']->id); }
  public function test_receipts_reject_expiration_before_receipt_date(): void { $x=$this->setupInventory();$this->expectException(ValidationException::class);app(InventoryService::class)->receive(['supply_item_id'=>$x['item']->id,'location_id'=>$x['loc']->id,'batch_number'=>'INVALID-DATE','received_on'=>now()->toDateString(),'expires_on'=>now()->subDay()->toDateString(),'quantity'=>1],$x['user']->id); }
}
